DROP TABLE IF EXISTS `pembelian_produk`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pembelian_produk` (
  `id_pembelian` varchar(255) NOT NULL,
  `id_supplier` varchar(255) NOT NULL,
  `id_akun` varchar(255) NOT NULL,
  `tanggal_pembelian` datetime NOT NULL,
  `tanggal_diterima` datetime DEFAULT NULL,
  `status_pembelian` enum('DIPESAN','DITERIMA','BATAL') NOT NULL DEFAULT 'DIPESAN',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id_pembelian`),
  KEY `pembelian_produk_id_supplier_foreign` (`id_supplier`),
  KEY `pembelian_produk_id_akun_foreign` (`id_akun`),
  CONSTRAINT `pembelian_produk_id_akun_foreign` FOREIGN KEY (`id_akun`) REFERENCES `akun` (`id_akun`) ON UPDATE CASCADE,
  CONSTRAINT `pembelian_produk_id_supplier_foreign` FOREIGN KEY (`id_supplier`) REFERENCES `supplier` (`id_supplier`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

