/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pengeluaran` (
  `id_pengeluaran` varchar(255) NOT NULL,
  `id_akun` varchar(255) NOT NULL,
  `id_pembelian` varchar(255) DEFAULT NULL,
  `tanggal_pengeluaran` datetime NOT NULL,
  `jenis_pengeluaran` enum('PEMBELIAN_PRODUK','LISTRIK','INTERNET','SEWA','ONGKIR','PERAWATAN','LAINNYA') NOT NULL,
  `nominal` decimal(12,2) NOT NULL,
  `keterangan` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id_pengeluaran`),
  UNIQUE KEY `pengeluaran_id_pembelian_unique` (`id_pembelian`),
  KEY `pengeluaran_id_akun_foreign` (`id_akun`),
  CONSTRAINT `pengeluaran_id_akun_foreign` FOREIGN KEY (`id_akun`) REFERENCES `akun` (`id_akun`) ON UPDATE CASCADE,
  CONSTRAINT `pengeluaran_id_pembelian_foreign` FOREIGN KEY (`id_pembelian`) REFERENCES `pembelian_produk` (`id_pembelian`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

