/*!40000 ALTER TABLE `pengeluaran` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `penjualan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `penjualan` (
  `id_penjualan` varchar(255) NOT NULL,
  `id_akun` varchar(255) NOT NULL,
  `tanggal_penjualan` datetime NOT NULL,
  `kanal_penjualan` enum('ONLINE','OFFLINE') NOT NULL,
  `metode_pembayaran` enum('QR','TUNAI') NOT NULL,
  `status_pembayaran` enum('MENUNGGU','BERHASIL','GAGAL') NOT NULL DEFAULT 'MENUNGGU',
  `referensi_pembayaran` varchar(255) DEFAULT NULL,
  `nominal_bayar` decimal(12,2) NOT NULL DEFAULT 0.00,
  `status_penjualan` enum('BARU','DIPROSES','DIKIRIM','SELESAI','BATAL') NOT NULL DEFAULT 'BARU',
  `alamat_pengiriman` text DEFAULT NULL,
  `poin_didapat` int(10) unsigned NOT NULL DEFAULT 0,
  `poin_digunakan` int(10) unsigned NOT NULL DEFAULT 0,
  `diskon_poin` decimal(12,2) NOT NULL DEFAULT 0.00,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id_penjualan`),
  UNIQUE KEY `penjualan_referensi_pembayaran_unique` (`referensi_pembayaran`),
  KEY `penjualan_id_akun_foreign` (`id_akun`),
  CONSTRAINT `penjualan_id_akun_foreign` FOREIGN KEY (`id_akun`) REFERENCES `akun` (`id_akun`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `penjualan` WRITE;
