DROP TABLE IF EXISTS `penjualan_member`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `penjualan_member` (
  `id_penjualan` varchar(255) NOT NULL,
  `id_akun_customer` varchar(255) NOT NULL,
  PRIMARY KEY (`id_penjualan`),
  KEY `penjualan_member_id_akun_customer_foreign` (`id_akun_customer`),
  CONSTRAINT `penjualan_member_id_akun_customer_foreign` FOREIGN KEY (`id_akun_customer`) REFERENCES `akun` (`id_akun`) ON UPDATE CASCADE,
  CONSTRAINT `penjualan_member_id_penjualan_foreign` FOREIGN KEY (`id_penjualan`) REFERENCES `penjualan` (`id_penjualan`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
